create extension if not exists pgcrypto;
create schema if not exists challenge;
create table challenge.scenarios(id uuid primary key default gen_random_uuid(),title text not null,domain text not null,description text,status text not null default 'draft',world jsonb not null default '{}',mission jsonb not null default '{}',temperature jsonb not null default '{}',duration jsonb not null default '{}',created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table challenge.seats(id uuid primary key default gen_random_uuid(),scenario_id uuid not null references challenge.scenarios(id) on delete cascade,name text not null,role text not null,seniority text,authority jsonb not null default '[]',information_scope jsonb not null default '{}',objectives jsonb not null default '[]');
create table challenge.competencies(id uuid primary key default gen_random_uuid(),domain text not null,code text not null unique,name text not null,rubric jsonb not null default '{}');
create table challenge.scenario_events(id uuid primary key default gen_random_uuid(),scenario_id uuid not null references challenge.scenarios(id) on delete cascade,event_key text not null,origin text not null,scheduled_at jsonb,trigger jsonb,payload jsonb not null default '{}',hidden boolean not null default false);
create table challenge.sessions(id uuid primary key default gen_random_uuid(),scenario_id uuid not null references challenge.scenarios(id),seat_id uuid not null references challenge.seats(id),candidate_id uuid not null references auth.users(id),status text not null default 'created',simulated_clock jsonb not null default '{}',world_state jsonb not null default '{}',started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table challenge.telemetry(id uuid primary key default gen_random_uuid(),session_id uuid not null references challenge.sessions(id) on delete cascade,actor text not null,action text not null,object_type text,object_id text,payload jsonb not null default '{}',simulated_at jsonb,created_at timestamptz not null default now());
create table challenge.messages(id uuid primary key default gen_random_uuid(),session_id uuid not null references challenge.sessions(id) on delete cascade,channel text not null,thread_key text,sender jsonb not null,recipients jsonb not null default '[]',subject text,body text not null,metadata jsonb not null default '{}',simulated_at jsonb,created_at timestamptz not null default now());
create table challenge.evidence(id uuid primary key default gen_random_uuid(),session_id uuid not null references challenge.sessions(id) on delete cascade,competency_id uuid not null references challenge.competencies(id),telemetry_ids uuid[] not null default '{}',evidence text not null,strength numeric not null check(strength between 0 and 1),confidence numeric not null check(confidence between 0 and 1),corroboration_required boolean not null default true,created_at timestamptz not null default now());
create table challenge.assessments(id uuid primary key default gen_random_uuid(),session_id uuid not null references challenge.sessions(id) on delete cascade,competency_id uuid not null references challenge.competencies(id),estimated_level text,confidence numeric not null check(confidence between 0 and 1),evidence_count int not null default 0,diversity numeric check(diversity between 0 and 1),rationale text,unique(session_id,competency_id));
alter table challenge.scenarios enable row level security;alter table challenge.seats enable row level security;alter table challenge.sessions enable row level security;alter table challenge.telemetry enable row level security;alter table challenge.messages enable row level security;alter table challenge.evidence enable row level security;alter table challenge.assessments enable row level security;
create policy "candidate reads sessions" on challenge.sessions for select using(candidate_id=auth.uid());create policy "candidate telemetry" on challenge.telemetry for all using(exists(select 1 from challenge.sessions s where s.id=session_id and s.candidate_id=auth.uid())) with check(exists(select 1 from challenge.sessions s where s.id=session_id and s.candidate_id=auth.uid()));create policy "candidate messages" on challenge.messages for select using(exists(select 1 from challenge.sessions s where s.id=session_id and s.candidate_id=auth.uid()));create policy "candidate assessments" on challenge.assessments for select using(exists(select 1 from challenge.sessions s where s.id=session_id and s.candidate_id=auth.uid()));
grant usage on schema challenge to authenticated;grant select,insert,update on all tables in schema challenge to authenticated;
